Ah. You could try something like this instead, but it's just a blind guess:
Spoiler:
plugin code XY
JavaScript:
/*:
 * @target MZ
 * @plugindesc Make certain pictures not shake with the screen.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/171740/
 * @orderAfter VisuMZ_0_CoreEngine
 * @help Another plugin must add shakeX and shakeY methods to Game_Screen.
 *
 * Free to use and/or modify for any project, no credit required.
 */
;void (function() {
'use strict';
  /**
   * Used in {@linkcode isNonShakePic}.
   * Pictures with a matching filename will shake in antiphase.
   */
  const NAME_RX = /!$/;  // "ends with !"

  /**
   * @param {Game_Picture} pic reference picture.
   * @returns {boolean} `true` iff `pic` is a "non-shake" picture.
   */
  const isNonShakePic = function(pic) {
    return pic && NAME_RX.test(pic.name());
  };

  /**
   * @param {Game_Picture} pic reference picture
   * @returns {number} additive X-offset for picture position.
   */
  const xOffset = function(pic) {
    return isNonShakePic(pic) ? -Math.round($gameScreen.shakeX()) : 0;
  };

  /**
   * @param {Game_Picture} pic reference picture
   * @returns {boolean} additive Y-offset for picture position.
   */
  const yOffset = function(pic) {
    return isNonShakePic(pic) ? -Math.round($gameScreen.shakeY()) : 0;
  };

  // Patch - cancel out X-offset due to spriteset shake.
  const alias = Sprite_Picture.prototype.updatePosition;
  Sprite_Picture.prototype.updatePosition = function() {
    alias.apply(this, arguments);
    this.x += xOffset(this.picture());
    this.y += yOffset(this.picture());
  };

})();
(Random shake would be 2 values, X and Y, but by default there is only 1 shake value. I've guessed that VisuStella might define the X/Y values as
shakeX
and
shakeY
respectively, using the same structure as the core scripts.)
Otherwise, you'd need to know what to write to replace those parts of the
xOffset
and
yOffset
functions.
Or you could find a different, non-obfuscated plugin that implements "random" style screen shake. That should make it easy to write compatible code.

