Oh, that does look helpful!
Based on those snippets, it doesn't look like the shake values get stored anywhere. But if you can edit the code then it should be a simple fix. E.g. for the "Random" type:
JavaScript:
// Get values for calculation.
const power = $gameScreen._shakePower * 0.75;
const speed = $gameScreen._shakeSpeed * 0.60;
const duration = $gameScreen._shakeDuration;

// Calculate values AND store them for later reference.
$gameScreen.shakeX = Math.round(Math.randomInt(power) - Math.randomInt(speed))
                   * (Math.min(duration, 30) * 0.5);
$gameScreen.shakeY = Math.round(Math.randomInt(power) - Math.randomInt(speed))
                   * (Math.min(duration, 30) * 0.5);

// Offset spriteset by calculated values.
this.x += $gameScreen.shakeX;
this.y += $gameScreen.shakeY;
...then reference those values in my plugin's
xOffset
and
yOffset
functions:
JavaScript:
const xOffset = function(pic) {
    return isNonShakePic(pic) ? -Math.round($gameScreen.shakeX) : 0;
  };

  const yOffset = function(pic) {
    return isNonShakePic(pic) ? -Math.round($gameScreen.shakeY) : 0;
  };
Hopefully that works!

